# Run locally using existing gh authentication; no tokens or provider keys are stored.
$ErrorActionPreference='Stop'; $CodespaceName='laughing-space-waffle-9795jw95xg64f7j79'; $Repo='taechasith/AI-should-kill-kid-or-elder'; $RemoteWorktree='/workspaces/ka-iro-krisis-v2-codespace'; $ResumeCommand="cd $RemoteWorktree && bash scripts/kairo_resume.sh"; $LogDir=Join-Path $env:LOCALAPPDATA 'KAIROKRISIS\logs'; New-Item -ItemType Directory -Force $LogDir|Out-Null
function Log($m){"$(Get-Date -Format o) | $m"|Add-Content (Join-Path $LogDir 'supervisor.log')}
if(!(Get-Command gh -ErrorAction SilentlyContinue)){throw 'GitHub CLI missing'}; gh auth status|Out-Null
$info=gh api "/user/codespaces/$CodespaceName"|ConvertFrom-Json; if($info.repository.full_name -ne $Repo){throw 'unexpected Codespace repository'}
if($info.state -ne 'Available'){Log "start requested: $($info.state)"; gh api --method POST "/user/codespaces/$CodespaceName/start"|Out-Null; for($i=0;$i -lt 40;$i++){Start-Sleep 15;$info=gh api "/user/codespaces/$CodespaceName"|ConvertFrom-Json;if($info.state -eq 'Available'){break}}}; if($info.state -ne 'Available'){throw 'Codespace unavailable'}
$health=gh codespace ssh -c $CodespaceName -- "cd $RemoteWorktree && bash scripts/kairo_health.sh"; Log "health=$health"; if($health -match '"runner":"(DONE|BLOCKED)"'){exit 0}; gh codespace ssh -c $CodespaceName -- "cd $RemoteWorktree && (flock -n /tmp/ka-iro-launch.lock nohup bash scripts/kairo_resume.sh >/tmp/ka-iro-autonomous.log 2>&1 & echo `$! >/tmp/ka-iro-autonomous.pid || true)"; Log 'resume launch requested'
